  function getDir(p = 0.1) {
    const rnd = new Random();
    let r = R.random_num(0, 1);
    let lp = 1 - p;
    let l = false;
    let ri = false;
    if (r >= lp) {
      l = true;
    } else if (r <= p) {
      ri = true;
    } else {
      l = true;
      ri = true;
    }
    return createVector(l, ri);
  }

  function drawosbranch(th, h, thres, ts, bp) {
    const rnd = new Random();
    ts *= R.random_num(0.6, 0.9);
    strokeWeight(ts);
    push();
    rotate(-th);
    line(0, 0, 0, -h);
    translate(0, -h);

    push(); // شاخه دوم
    rotate(radians(R.random_num(20, 40)));

    pop();

    let v = getDir(R.random_num(0.4, 0.6));
    let l = v.x;
    let r = v.y;

    osbranch(h, l, r, thres, ts, bp);
    pop();
  }
  function osbranch(h, l, r, thres = 6, ts = 3, bp = []) {
    const rnd = new Random();
    let a = R.random_num(-30, 30);
    let s = 6;
    let t = radians(a);

    h *= R.random_num(0.7, 1);

    let i = bp.length;
    bp[i] = createVector(bp[i - 1].x + h * cos(t), bp[i - 1].y - h * sin(t));

    if (bp[i].x > 0 && bp[i].y > 0) {
      if (h > thres) {
        if (r) {
          drawosbranch(t, h, thres, ts, bp);
        }
        if (l) {
          drawosbranch(-t, h, thres, ts, bp);
        }
      } else {
        fill(randomColorx(Summer5));
        stroke(randomColorx(Summer5));
        strokeWeight(R.random_num(0, 4));
       line(0, 0, R.random_num(0, 20), R.random_num(0, 50));
        translate(0, -h);
      }
    }
  }
  function multiosbranch(bs, l, r, ts = new Random().random_num(100, 600), nb = new Random().random_num(30, 200)) {
    const rnd = new Random();
    for (let i = 0; i <= nb; i++) {
      const os = R.random_num(20, 200);
      let bp = [];
      bp[0] = createVector(2000 / 2, 1000 - os);
      osbranch(bs, l, r, thres = R.random_num(10, 20), ts = ts, bp);
    }
  }

