  let left_probability = 1 - probability
  let left9 = false;
  let right9 = false;
  if (random_int >= left_probability) {
  left9 = true
  }
  else if (random_int <= probability) {
  left9 = true
  }
  else {
  left9 = true
  right9 = true
  }
  return createVector(left9, right9)
  }

  function draw_branch_9(theta, h, threshold, first_thickness_size_9, branch_positions) {
