  function branch_9(h, left9, right9, threshold = 6, first_thickness_size_9 = 3, branch_positions = []) {

    let rnd = new Random();
    let a = R.random_num(-30, 30);
    let steps = 6;
    let theta = radians(a);

    h *= R.random_num(0.7, 1);

    let i = branch_positions.length;
    branch_positions[i] = createVector(branch_positions[i-1].x + h*cos(theta), branch_positions[i-1].y - h*sin(theta));

    if (branch_positions[i].x > 0 && branch_positions[i].y > 0) {
      if (h > threshold) {
        if (right9) {
          draw_branch_9(theta, h, threshold, first_thickness_size_9, branch_positions);
        }
        if (left9) {
          draw_branch_9(-theta, h, threshold, first_thickness_size_9, branch_positions);
        }
      }
