function generateRandomDate(startDate, endDate) {
  // محاسبهٔ میلی‌ثانیه‌ی متناظر با تاریخ شروع و پایان
  let startMillis = startDate.getTime();
  let endMillis = endDate.getTime();

  // تولید یک عدد تصادفی بین میلی‌ثانیه‌های شروع و پایان
  let randomMillis = R.random_num(startMillis, endMillis);

  // تبدیل عدد تصادفی به تاریخ
  let randomDate = new Date(randomMillis);

  return randomDate;
}
